<?php require_once 'config/config.php'; if(user()) redirect('dashboard.php'); $error='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$name=trim($_POST['name']??'');$email=trim($_POST['email']??'');$phone=trim($_POST['phone']??'');$pass=$_POST['password']??'';
if(strlen($name)<2||!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($pass)<8)$error='Use a valid name/email and password of at least 8 characters.';
else {try{$st=db()->prepare("INSERT INTO users(name,email,phone,password_hash) VALUES(?,?,?,?)");$st->execute([$name,$email,$phone,password_hash($pass,PASSWORD_DEFAULT)]);flash('Account created. Please log in.');redirect('index.php');}catch(PDOException $e){$error=$e->getCode()==='23000'?'Email already registered.':'Could not create account.';}}}
$title='Create account';include 'includes/header.php';?>
<div class="login-wrap"><div class="card login-card p-4 p-lg-5"><h3 class="fw-bold">Create account</h3><p class="small-muted">Then create a room or join one with a room code.</p><?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?><form method="post"><input type="hidden" name="csrf" value="<?=csrf()?>"><input class="form-control mb-3" name="name" placeholder="Full name" required><input class="form-control mb-3" name="email" type="email" placeholder="Email" required><input class="form-control mb-3" name="phone" placeholder="Phone (optional)"><input class="form-control mb-3" name="password" type="password" placeholder="Password (8+ characters)" required><button class="btn btn-dark w-100">Create account</button></form><a class="d-block text-center mt-3" href="index.php">Back to login</a></div></div><?php include 'includes/footer.php';?>